{"Table":"kersef_tb_user","Create Table":"CREATE TABLE `kersef_tb_user` (\n  `id` varchar(36) NOT NULL,\n  `userId` varchar(255) NOT NULL,\n  `guildId` varchar(255) NOT NULL,\n  `name` varchar(255) DEFAULT NULL,\n  `xp` int(11) NOT NULL DEFAULT 0,\n  `level` int(11) NOT NULL DEFAULT 1,\n  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),\n  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),\n  `power_level` int(11) DEFAULT NULL,\n  `last_update_power_level` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),\n  PRIMARY KEY (`userId`,`guildId`),\n  KEY `IDX_user_guild_xp` (`guildId`,`xp`),\n  KEY `IDX_user_guild_name` (`guildId`,`name`)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci","json":{"name":"kersef_tb_user.sql","path":"files/sql/rod/kersef_tb_user.sql","sha":"141e7141d3c7038adebf48c7591572c5f30c39e8","size":1262011,"url":"https://api.github.com/repos/rodcordeiro/shares/contents/files/sql/rod/kersef_tb_user.sql?ref=master","html_url":"https://github.com/rodcordeiro/shares/blob/master/files/sql/rod/kersef_tb_user.sql","git_url":"https://api.github.com/repos/rodcordeiro/shares/git/blobs/141e7141d3c7038adebf48c7591572c5f30c39e8","download_url":"https://raw.githubusercontent.com/rodcordeiro/shares/master/files/sql/rod/kersef_tb_user.sql","type":"file","content":"","encoding":"none","_links":{"self":"https://api.github.com/repos/rodcordeiro/shares/contents/files/sql/rod/kersef_tb_user.sql?ref=master","git":"https://api.github.com/repos/rodcordeiro/shares/git/blobs/141e7141d3c7038adebf48c7591572c5f30c39e8","html":"https://github.com/rodcordeiro/shares/blob/master/files/sql/rod/kersef_tb_user.sql"}},"pairedItem":{"item":30},"index":30}